#include "render_camera_candidate.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");auto c=diagnosticRenderCameraCandidate();auto p=c.clip({25,30,65});std::array<float,4>expected{.5f,-.5f,.5f,1};for(size_t i=0;i<4;++i)if(std::abs(p[i]-expected[i])>1e-6f)throw std::runtime_error("projection");c.rows[3]=.25f;if(std::abs(c.clip({25,30,65})[0]-.75f)>1e-6f)throw std::runtime_error("camera translation");c.rows[15]=2;if(std::abs(c.depth({25,30,65})-.25)>1e-6)throw std::runtime_error("homogeneous depth");size_t rejected=0;c.rows[15]=0;try{c.depth({0,0,0});}catch(const std::runtime_error&){++rejected;}c.rows[0]=std::numeric_limits<float>::infinity();try{c.clip({1,0,0});}catch(const std::runtime_error&){++rejected;}if(rejected!=2)throw std::runtime_error("camera rejection");std::cout<<"x64 render camera projection passed rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
